<?php
if(PHP_SAPI!=='cli'||getenv('APP_ENV')!=='testing'||!preg_match('/^impe_test_handly_aliados_v4_[a-z0-9_]+$/D',getenv('IMPE_DB_NAME')?:''))exit(2);
require_once __DIR__.'/../config/db_connection.php';require_once __DIR__.'/../app/services/ConvocatoriaBorradorService.php';
$db=(new Database())->connect(false);$service=new ConvocatoriaBorradorService($db);$checks=0;
$check=static function($v,$label)use(&$checks){if(!$v)throw new RuntimeException($label);$checks++;echo "OK $label\n";};
$reject=static function(callable $fn,int $code,string $label)use($check){try{$fn();}catch(DomainException $e){$check($e->getCode()===$code,$label);return;}throw new RuntimeException('Aceptado: '.$label);};
$marketing=['usuario_id'=>4,'rol_id'=>5,'rol'=>'Marketing','permisos'=>['convenios.ver','convocatorias.ver','convocatorias.crear','formularios_aliados.gestionar_enlaces']];$_SESSION=$marketing;
$before=(int)$db->query('SELECT COUNT(*) FROM convocatorias')->fetch_row()[0];
$open=$service->abrir('institucional',10);$draft=$open['borrador'];$id=$draft['id'];$url=$open['contexto']['url'];
$check($service->abrir('institucional',10)['borrador']['id']===$id,'abrir repetidamente recupera el mismo borrador del propietario');
$data=['bachillerato-general'=>['titulo'=>'V4 DB incompleto','fecha_inicio'=>'','fecha_termino'=>'','estado'=>'1','clasificacion'=>'bachillerato|bachillerato-general']];$key=bin2hex(random_bytes(32));
$saved=$service->guardar($id,$draft['version'],$key,$data);
$check($saved['programas']->{'bachillerato-general'}['titulo']==='V4 DB incompleto'&&!$saved['completitud']->{'bachillerato-general'},'se persiste texto incompleto sin crear convocatorias');
$check(isset($saved['programas']->{'bachillerato-general'}['actualizado_at'])&&$saved['programas']->{'bachillerato-general'}['actualizado_por']===4,'programa conserva fecha y último usuario en el servidor');
$check(json_encode($service->guardar($id,$draft['version'],$key,$data))===json_encode($saved),'respuesta perdida de autoguardado se recupera idempotentemente');
$reject(fn()=>$service->guardar($id,$draft['version'],bin2hex(random_bytes(32)),$data),409,'otra pestaña con versión antigua no sobrescribe');
$reject(fn()=>$service->guardar($id,$saved['version'],$key,[]),409,'una clave no puede reutilizarse con datos diferentes');
$reject(fn()=>$service->guardar($id,$saved['version'],bin2hex(random_bytes(32)),['ingles'=>[]]),422,'el programa se revalida contra la oferta real');
$check($service->cargar($id)['version']===$saved['version'],'errores de validación no incrementan versión ni destruyen el borrador');
$manual=(int)$db->query("SELECT id FROM aliados_manuales WHERE nombre_entidad='V4 Manual'")->fetch_row()[0];
$other=$service->abrir('manual',$manual)['borrador'];$check($other['id']!==$id&&(array)$other['programas']===[],'otro aliado tiene un borrador aislado');
$_SESSION=array_replace($marketing,['usuario_id'=>3]);$reject(fn()=>$service->cargar($id),404,'otro usuario no puede leer el borrador por su identificador');
$own=$service->abrir('institucional',10)['borrador'];$check($own['id']!==$id,'dos usuarios conservan borradores independientes del mismo aliado');
$_SESSION=['usuario_id'=>2,'rol_id'=>6,'rol'=>'Cuenta Clave','permisos'=>['convenios.ver','convocatorias.ver','convocatorias.crear']];
$cc=$service->abrir('institucional',10)['borrador'];
$db->query('UPDATE asignaciones_territorio SET activo=0 WHERE usuario_id=2');
$reject(fn()=>$service->cargar($cc['id']),403,'revocar el territorio impide recuperar un borrador existente');
$db->query('UPDATE asignaciones_territorio SET activo=1 WHERE usuario_id=2');
$_SESSION=$marketing;(new AliadoRegistroService($db))->enlace('institucional',10,'deshabilitar');
$check($service->cargar($id)['id']===$id,'Registro deshabilitado conserva el borrador');
$check($service->abrir('institucional',10)['contexto']['url']===$url,'el token y enlace original no se reconstruyen');
(new AliadoRegistroService($db))->enlace('institucional',10,'habilitar');
$discard=$service->descartar($id,$saved['version'],bin2hex(random_bytes(32)));
$check($discard['estado']==='descartado','descartar es una acción independiente del cierre');
$check($service->abrir('institucional',10)['borrador']['id']!==$id,'tras descartar se crea un borrador nuevo sin reutilizar datos');
$check((int)$db->query('SELECT COUNT(*) FROM convocatorias')->fetch_row()[0]===$before,'editar y descartar borradores nunca publica ni altera conteos');
echo "PASS $checks comprobaciones DB V4 · ".$db->server_info."\n";
